     6→/// Preferences Service for App Settings
     7→///
     8→/// Manages user preferences and settings using Hive for persistence.
     9→class PreferencesService {
    10→  static const String _settingsBoxName = 'app_settings';
    11→  static const String _settingsKey = 'settings';
    12→
    13→  static Box<AppSettings>? _settingsBox;
    14→  static AppSettings? _cachedSettings;
    15→
    16→  /// Initialize preferences storage
    17→  ///
    18→  /// Must be called before using any preferences operations.
    19→  static Future<void> initialize() async {
    20→    try {
    21→      if (!Hive.isAdapterRegistered(2)) {
    22→        Hive.registerAdapter(AppSettingsAdapter());
    23→      }
    24→
    25→      _settingsBox = await Hive.openBox<AppSettings>(_settingsBoxName);
    26→
    27→      // Load or create default settings
    28→      _cachedSettings = _settingsBox!.get(_settingsKey);
    29→      if (_cachedSettings == null) {
    30→        _cachedSettings = AppSettings.defaultSettings();
    31→        await _settingsBox!.put(_settingsKey, _cachedSettings!);
    32→      }
    33→
    34→      debugPrint('[Preferences] Settings initialized');
    35→    } catch (e) {
    36→      debugPrint('[Preferences] Error initializing: $e');
    37→      rethrow;
    38→    }
    39→  }
    40→
    41→  /// Get current settings
    42→  static AppSettings get settings {
    43→    if (_cachedSettings == null) {
    44→      throw StateError('PreferencesService not initialized');
    45→    }
    46→    return _cachedSettings!;
    47→  }
    48→
    49→  /// Update settings
    50→  static Future<void> updateSettings(AppSettings newSettings) async {
    51→    await _settingsBox!.put(_settingsKey, newSettings);
    52→    _cachedSettings = newSettings;
    53→    debugPrint('[Preferences] Settings updated');
    54→  }
    55→
    56→  /// Check if preferences are initialized
    57→  static bool get isInitialized => _cachedSettings != null;
    58→
    59→  /// Reset to default settings
    60→  static Future<void> resetToDefaults() async {
    61→    final defaultSettings = AppSettings.defaultSettings();
    62→    await updateSettings(defaultSettings);
    63→    debugPrint('[Preferences] Reset to default settings');
    64→  }
    65→
    66→  /// Close the settings box
    67→  static Future<void> close() async {
    68→    await _settingsBox?.close();
    69→    _settingsBox = null;
    70→    _cachedSettings = null;
    71→    debugPrint('[Preferences] Preferences service closed');
    72→  }
    73→}
    74→

