     3→/// Theme extension for storing gradient and shadow properties
     4→///
     5→/// This extension allows us to store custom gradient definitions
     6→/// and shadows that aren't part of the standard Material ThemeData.
     7→///
     8→/// Usage:
     9→/// ```dart
    10→/// final themeExt = AppThemeExtension.of(context);
    11→/// Container(
    12→///   decoration: BoxDecoration(
    13→///     gradient: themeExt.primaryGradient,
    14→///   ),
    15→/// )
    16→/// ```
    17→@immutable
    18→class AppThemeExtension extends ThemeExtension<AppThemeExtension> {
    19→  /// Primary gradient (used for main UI elements)
    20→  final Gradient primaryGradient;
    21→
    22→  /// Secondary gradient (used for accents and secondary elements)
    23→  final Gradient secondaryGradient;
    24→
    25→  /// Accent gradient (used for highlights and CTAs)
    26→  final Gradient accentGradient;
    27→
    28→  /// Background gradient (subtle overlay on surfaces)
    29→  final Gradient backgroundGradient;
    30→
    31→  /// Surface gradient (overlay for cards and containers)
    32→  final Gradient surfaceGradient;
    33→
    34→  /// Shadow for cards
    35→  final List<BoxShadow> cardShadow;
    36→
    37→  /// Shadow for elevated elements
    38→  final List<BoxShadow> elevatedShadow;
    39→
    40→  const AppThemeExtension({
    41→    required this.primaryGradient,
    42→    required this.secondaryGradient,
    43→    required this.accentGradient,
    44→    required this.backgroundGradient,
    45→    required this.surfaceGradient,
    46→    required this.cardShadow,
    47→    required this.elevatedShadow,
    48→  });
    49→
    50→  @override
    51→  AppThemeExtension copyWith({
    52→    Gradient? primaryGradient,
    53→    Gradient? secondaryGradient,
    54→    Gradient? accentGradient,
    55→    Gradient? backgroundGradient,
    56→    Gradient? surfaceGradient,
    57→    List<BoxShadow>? cardShadow,
    58→    List<BoxShadow>? elevatedShadow,
    59→  }) {
    60→    return AppThemeExtension(
    61→      primaryGradient: primaryGradient ?? this.primaryGradient,
    62→      secondaryGradient: secondaryGradient ?? this.secondaryGradient,
    63→      accentGradient: accentGradient ?? this.accentGradient,
    64→      backgroundGradient: backgroundGradient ?? this.backgroundGradient,
    65→      surfaceGradient: surfaceGradient ?? this.surfaceGradient,
    66→      cardShadow: cardShadow ?? this.cardShadow,
    67→      elevatedShadow: elevatedShadow ?? this.elevatedShadow,
    68→    );
    69→  }
    70→
    71→  @override
    72→  AppThemeExtension lerp(ThemeExtension<AppThemeExtension>? other, double t) {
    73→    if (other is! AppThemeExtension) {
    74→      return this;
    75→    }
    76→    // Gradients don't interpolate well, so we'll just switch at t > 0.5
    77→    return t < 0.5 ? this : other;
    78→  }
    79→
    80→  /// Helper method to access theme extension from context
    81→  static AppThemeExtension of(BuildContext context) {
    82→    final extension = Theme.of(context).extension<AppThemeExtension>();
    83→    if (extension == null) {
    84→      throw FlutterError(
    85→        'AppThemeExtension not found in theme. '
    86→        'Make sure AppTheme is properly configured.',
    87→      );
    88→    }
    89→    return extension;
    90→  }
    91→
    92→  /// Helper method to safely access theme extension (returns null if not found)
    93→  static AppThemeExtension? maybeOf(BuildContext context) {
    94→    return Theme.of(context).extension<AppThemeExtension>();
    95→  }
    96→}
