    32→class MyApp extends StatefulWidget {
    33→  const MyApp({super.key});
    34→
    35→  @override
    36→  State<MyApp> createState() => _MyAppState();
    37→}
    38→
    39→class _MyAppState extends State<MyApp> {
    40→  StreamSubscription? _linkSubscription;
    41→
    42→  @override
    43→  void initState() {
    44→    super.initState();
    45→    _initDeepLinks();
    46→  }
    47→
    48→  void _initDeepLinks() {
    49→    // Handle initial link (app opened via deep link)
    50→    getInitialLink().then((String? initialLink) {
    51→      if (initialLink != null) {
    52→        _handleDeepLink(initialLink);
    53→      }
    54→    });
    55→
    56→    // Listen for deep links while app is running
    57→    _linkSubscription = linkStream.listen(
    58→      (String? link) {
    59→        if (link != null) {
    60→          _handleDeepLink(link);
    61→        }
    62→      },
    63→      onError: (err) {
    64→        debugPrint('Deep link error: $err');
    65→      },
    66→    );
    67→  }
    68→
    69→  void _handleDeepLink(String link) {
    70→    debugPrint('Received deep link: $link');
    71→    final uri = Uri.parse(link);
    72→    
    73→    if (uri.scheme == 'sss') {
    74→      WidgetsBinding.instance.addPostFrameCallback((_) {
    75→        if (mounted) {
    76→          if (uri.host == 'container') {
    77→            // Handle container deep link: sss://container/<id>
    78→            final containerId = uri.pathSegments.isNotEmpty ? uri.pathSegments.first : '';
    79→            if (containerId.isNotEmpty) {
    80→              final container = ContainerService.getContainer(containerId);
    81→              if (container != null) {
    82→                Navigator.of(context).pushReplacement(
    83→                  MaterialPageRoute(
    84→                    builder: (context) => ContainerDetailScreen(containerId: containerId),
    85→                  ),
    86→                );
    87→                return;
    88→              }
    89→            }
    90→          } else if (uri.host == 'qr') {
    91→            // Handle QR/NFC deep link: sss://qr/<id>
    92→            final id = uri.pathSegments.isNotEmpty ? uri.pathSegments.first : '';
    93→            if (id.isNotEmpty) {
    94→              // Check if it's linked to a container
    95→              final container = ContainerService.getContainerByQRCode(id);
    96→              if (container != null) {
    97→                Navigator.of(context).pushReplacement(
    98→                  MaterialPageRoute(
    99→                    builder: (context) => ContainerDetailScreen(containerId: container.id),
   100→                  ),
   101→                );
   102→                return;
   103→              }
   104→
   105→              // Check if it's a QR code or NFC tag
   106→              final qrData = QRService.getQRDataById(id);
   107→              if (qrData != null) {
   108→                Navigator.of(context).pushReplacement(
   109→                  MaterialPageRoute(
   110→                    builder: (context) => QRDetailScreen(qrId: id),
   111→                  ),
   112→                );
   113→                return;
   114→              }
   115→
   116→              // Try NFC
   117→              final nfcData = NFCService.getNFCTagDataById(id);
   118→              if (nfcData != null) {
   119→                // Check if NFC is linked to a container
   120→                final nfcContainer = ContainerService.getContainerByNFCTag(id);
   121→                if (nfcContainer != null) {
   122→                  Navigator.of(context).pushReplacement(
   123→                    MaterialPageRoute(
   124→                      builder: (context) => ContainerDetailScreen(containerId: nfcContainer.id),
   125→                    ),
   126→                  );
   127→                  return;
   128→                }
   129→
   130→                Navigator.of(context).pushReplacement(
   131→                  MaterialPageRoute(
   132→                    builder: (context) => NFCDetailScreen(nfcId: id),
   133→                  ),
   134→                );
   135→                return;
   136→              }
   137→            }
   138→          }
   139→
   140→          // Not found, show error
   141→          Navigator.of(context).pushReplacement(
   142→            MaterialPageRoute(
   143→              builder: (context) => Scaffold(
   144→                appBar: AppBar(
   145→                  title: const Text('Not Found'),
   146→                ),
   147→                body: Center(
   148→                  child: Column(
   149→                    mainAxisAlignment: MainAxisAlignment.center,
   150→                    children: [
   151→                      const Icon(Icons.error_outline, size: 64, color: Colors.red),
   152→                      const SizedBox(height: 16),
   153→                      const Text('Item not found'),
   154→                      const SizedBox(height: 24),
   155→                      ElevatedButton(
   156→                        onPressed: () => Navigator.pop(context),
   157→                        child: const Text('Go Back'),
   158→                      ),
   159→                    ],
   160→                  ),
   161→                ),
   162→              ),
   163→            ),
   164→          );
   165→        }
   166→      });
   167→    }
   168→  }
   169→
   170→  @override
   171→  void dispose() {
   172→    _linkSubscription?.cancel();
   173→    super.dispose();
   174→  }
   175→
   176→  @override
   177→  Widget build(BuildContext context) {
   178→    return MaterialApp(
   179→      title: 'SSS - Search & Scan',
   180→      theme: AppTheme.lightTheme,
   181→      darkTheme: AppTheme.darkTheme,
   182→      themeMode: ThemeMode.system,
   183→      home: const ContainerListScreen(),
   184→      onGenerateRoute: (settings) {
   185→        // Handle deep link routes
   186→        if (settings.name?.startsWith('sss://') ?? false) {
   187→          final uri = Uri.parse(settings.name!);
   188→          
   189→          if (uri.host == 'container') {
   190→            final containerId = uri.pathSegments.isNotEmpty ? uri.pathSegments.first : '';
   191→            if (containerId.isNotEmpty) {
   192→              return MaterialPageRoute(
   193→                builder: (context) => ContainerDetailScreen(containerId: containerId),
   194→              );
   195→            }
   196→          } else if (uri.host == 'qr') {
   197→            final id = uri.pathSegments.isNotEmpty ? uri.pathSegments.first : '';
   198→            if (id.isNotEmpty) {
   199→              // Check if linked to container
   200→              final container = ContainerService.getContainerByQRCode(id);
   201→              if (container != null) {
   202→                return MaterialPageRoute(
   203→                  builder: (context) => ContainerDetailScreen(containerId: container.id),
   204→                );
   205→              }
   206→
   207→              // Try QR first, then NFC
   208→              final qrData = QRService.getQRDataById(id);
   209→              if (qrData != null) {
   210→                return MaterialPageRoute(
   211→                  builder: (context) => QRDetailScreen(qrId: id),
   212→                );
   213→              } else {
   214→                final nfcData = NFCService.getNFCTagDataById(id);
   215→                if (nfcData != null) {
   216→                  final nfcContainer = ContainerService.getContainerByNFCTag(id);
   217→                  if (nfcContainer != null) {
   218→                    return MaterialPageRoute(
   219→                      builder: (context) => ContainerDetailScreen(containerId: nfcContainer.id),
   220→                    );
   221→                  }
   222→                  return MaterialPageRoute(
   223→                    builder: (context) => NFCDetailScreen(nfcId: id),
   224→                  );
   225→                }
   226→              }
   227→            }
   228→          }
   229→        }
   230→        return null;
   231→      },
   232→    );
   233→  }
   234→}
