     3→/// Design token: Border radius system for modern classic aesthetic
     4→///
     5→/// Usage:
     6→/// ```dart
     7→/// Container(
     8→///   decoration: BoxDecoration(
     9→///     borderRadius: AppRadius.roundedLG,
    10→///   ),
    11→/// )
    12→/// ```
    13→class AppRadius {
    14→  AppRadius._();
    15→
    16→  // Radius values (modern rounded corners with classic undertones)
    17→  static const double xs = 4.0;      // Subtle
    18→  static const double sm = 8.0;      // Small chips, badges
    19→  static const double md = 12.0;     // Buttons, inputs
    20→  static const double lg = 16.0;     // Cards, containers
    21→  static const double xl = 20.0;     // Large containers
    22→  static const double xxl = 24.0;    // Prominent elements
    23→  static const double circular = 999.0; // Fully rounded (pills, avatars)
    24→
    25→  // BorderRadius helpers
    26→  static BorderRadius get roundedXS => BorderRadius.circular(xs);
    27→  static BorderRadius get roundedSM => BorderRadius.circular(sm);
    28→  static BorderRadius get roundedMD => BorderRadius.circular(md);
    29→  static BorderRadius get roundedLG => BorderRadius.circular(lg);
    30→  static BorderRadius get roundedXL => BorderRadius.circular(xl);
    31→  static BorderRadius get roundedXXL => BorderRadius.circular(xxl);
    32→  static BorderRadius get roundedFull => BorderRadius.circular(circular);
    33→
    34→  // Radius helpers (for use with single corners)
    35→  static Radius get radiusXS => Radius.circular(xs);
    36→  static Radius get radiusSM => Radius.circular(sm);
    37→  static Radius get radiusMD => Radius.circular(md);
    38→  static Radius get radiusLG => Radius.circular(lg);
    39→  static Radius get radiusXL => Radius.circular(xl);
    40→  static Radius get radiusXXL => Radius.circular(xxl);
    41→  static Radius get radiusFull => Radius.circular(circular);
    42→
    43→  // Specific use-case patterns
    44→  static BorderRadius get buttonRadius => roundedMD;
    45→  static BorderRadius get cardRadius => roundedLG;
    46→  static BorderRadius get inputRadius => roundedMD;
    47→  static BorderRadius get chipRadius => roundedSM;
    48→  static BorderRadius get dialogRadius => roundedXL;
    49→  static BorderRadius get sheetRadius => const BorderRadius.vertical(
    50→    top: Radius.circular(xl),
    51→  );
    52→
    53→  // Custom helpers for top-only or bottom-only rounding
    54→  static BorderRadius topOnly(double radius) => BorderRadius.vertical(
    55→    top: Radius.circular(radius),
    56→  );
    57→
    58→  static BorderRadius bottomOnly(double radius) => BorderRadius.vertical(
    59→    bottom: Radius.circular(radius),
    60→  );
    61→
    62→  static BorderRadius leftOnly(double radius) => BorderRadius.horizontal(
    63→    left: Radius.circular(radius),
    64→  );
    65→
    66→  static BorderRadius rightOnly(double radius) => BorderRadius.horizontal(
    67→    right: Radius.circular(radius),
    68→  );
    69→}
