     9→/// Preferences Service for App Settings
    10→///
    11→/// Manages user preferences and settings using Hive for persistence.
    12→/// Provides reactive updates via ValueNotifier for theme and settings changes.
    13→class PreferencesService {
    14→  static const String _settingsBoxName = 'app_settings';
    15→  static const String _settingsKey = 'settings';
    16→
    17→  static Box<AppSettings>? _settingsBox;
    18→  static AppSettings? _cachedSettings;
    19→
    20→  /// ValueNotifier for reactive settings updates
    21→  /// Listen to this for theme/font changes that require app-wide rebuild
    22→  static final ValueNotifier<AppSettings?> settingsNotifier = ValueNotifier(
    23→    null,
    24→  );
    25→
    26→  /// Initialize preferences storage
    27→  ///
    28→  /// Must be called before using any preferences operations.
    29→  static Future<void> initialize() async {
    30→    try {
    31→      if (!Hive.isAdapterRegistered(2)) {
    32→        Hive.registerAdapter(AppSettingsAdapter());
    33→      }
    34→
    35→      _settingsBox = await Hive.openBox<AppSettings>(_settingsBoxName);
    36→
    37→      // Load or create default settings
    38→      _cachedSettings = _settingsBox!.get(_settingsKey);
    39→      if (_cachedSettings == null) {
    40→        _cachedSettings = AppSettings.defaultSettings();
    41→        await _settingsBox!.put(_settingsKey, _cachedSettings!);
    42→      }
    43→
    44→      // Update notifier
    45→      settingsNotifier.value = _cachedSettings;
    46→
    47→      debugPrint('[Preferences] Settings initialized');
    48→    } catch (e) {
    49→      debugPrint('[Preferences] Error initializing: $e');
    50→      rethrow;
    51→    }
    52→  }
    53→
    54→  /// Get current settings
    55→  static AppSettings get settings {
    56→    if (_cachedSettings == null) {
    57→      throw StateError('PreferencesService not initialized');
    58→    }
    59→    return _cachedSettings!;
    60→  }
    61→
    62→  /// Update settings
    63→  static Future<void> updateSettings(AppSettings newSettings) async {
    64→    await _settingsBox!.put(_settingsKey, newSettings);
    65→    _cachedSettings = newSettings;
    66→    settingsNotifier.value = newSettings;
    67→    debugPrint('[Preferences] Settings updated');
    68→  }
    69→
    70→  /// Check if preferences are initialized
    71→  static bool get isInitialized => _cachedSettings != null;
    72→
    73→  /// Reset to default settings
    74→  static Future<void> resetToDefaults() async {
    75→    final defaultSettings = AppSettings.defaultSettings();
    76→    await updateSettings(defaultSettings);
    77→    debugPrint('[Preferences] Reset to default settings');
    78→  }
    79→
    80→  /// Close the settings box
    81→  static Future<void> close() async {
    82→    await _settingsBox?.close();
    83→    _settingsBox = null;
    84→    _cachedSettings = null;
    85→    settingsNotifier.value = null;
    86→    debugPrint('[Preferences] Preferences service closed');
    87→  }
    88→
    89→  // ========== Theme Helpers ==========
    90→
    91→  /// Get current theme mode
    92→  static AppThemeMode get themeMode => settings.themeMode;
    93→
    94→  /// Update theme mode
    95→  static Future<void> setThemeMode(AppThemeMode mode) async {
    96→    await updateSettings(settings.copyWith(themeMode: mode));
    97→  }
    98→
    99→  /// Get current font scale
   100→  static double get fontScale => settings.fontScale.scale;
   101→
   102→  /// Update font scale
   103→  static Future<void> setFontScale(FontScaleOption scale) async {
   104→    await updateSettings(settings.copyWith(fontScale: scale));
   105→  }
   106→
   107→  // ========== Storage Helpers ==========
   108→
   109→  /// Get the Hive storage path
   110→  static Future<String> getStoragePath() async {
   111→    final directory = await getApplicationDocumentsDirectory();
   112→    return directory.path;
   113→  }
   114→
   115→  /// Get image cache directory path
   116→  static Future<String> getImageCachePath() async {
   117→    final cacheDir = await getTemporaryDirectory();
   118→    return '${cacheDir.path}/image_cache';
   119→  }
   120→
   121→  /// Get current image cache size in bytes
   122→  static Future<int> getImageCacheSizeBytes() async {
   123→    try {
   124→      final cachePath = await getImageCachePath();
   125→      final cacheDir = Directory(cachePath);
   126→
   127→      if (!await cacheDir.exists()) {
   128→        return 0;
   129→      }
   130→
   131→      int totalSize = 0;
   132→      await for (final entity in cacheDir.list(recursive: true)) {
   133→        if (entity is File) {
   134→          totalSize += await entity.length();
   135→        }
   136→      }
   137→      return totalSize;
   138→    } catch (e) {
   139→      debugPrint('[Preferences] Error getting cache size: $e');
   140→      return 0;
   141→    }
   142→  }
   143→
   144→  /// Format bytes to human readable string
   145→  static String formatBytes(int bytes) {
   146→    if (bytes < 1024) return '$bytes B';
   147→    if (bytes < 1024 * 1024) return '${(bytes / 1024).toStringAsFixed(1)} KB';
   148→    if (bytes < 1024 * 1024 * 1024) {
   149→      return '${(bytes / (1024 * 1024)).toStringAsFixed(1)} MB';
   150→    }
   151→    return '${(bytes / (1024 * 1024 * 1024)).toStringAsFixed(1)} GB';
   152→  }
   153→
   154→  /// Clear image cache
   155→  static Future<void> clearImageCache() async {
   156→    try {
   157→      final cachePath = await getImageCachePath();
   158→      final cacheDir = Directory(cachePath);
   159→
   160→      if (await cacheDir.exists()) {
   161→        await cacheDir.delete(recursive: true);
   162→        await cacheDir.create();
   163→        debugPrint('[Preferences] Image cache cleared');
   164→      }
   165→    } catch (e) {
   166→      debugPrint('[Preferences] Error clearing image cache: $e');
   167→    }
   168→  }
   169→
   170→  /// Get default export path
   171→  static Future<String> getDefaultExportPath() async {
   172→    if (settings.defaultExportPath != null) {
   173→      return settings.defaultExportPath!;
   174→    }
   175→
   176→    final directory = await getApplicationDocumentsDirectory();
   177→    return '${directory.path}/exports';
   178→  }
   179→
   180→  /// Set default export path
   181→  static Future<void> setDefaultExportPath(String path) async {
   182→    await updateSettings(settings.copyWith(defaultExportPath: path));
   183→  }
   184→
   185→  /// Get max image cache size in bytes
   186→  static int get maxImageCacheBytes =>
   187→      settings.imageCacheSize.sizeInMB * 1024 * 1024;
   188→
   189→  /// Update image cache size setting
   190→  static Future<void> setImageCacheSize(ImageCacheSize size) async {
   191→    await updateSettings(settings.copyWith(imageCacheSize: size));
   192→  }
   193→}
